### Server-side session validation via get-session endpoint

Source: https://github.com/better-auth/better-auth/blob/main/packages/better-auth/src/api/routes/session.ts

Better Auth validates sessions server-side by reading the `session_token` signed cookie, looking it up in the database via `findSession()`, checking expiry (deleting expired sessions), and returning `{ session, user }`. The `getSessionFromCtx` helper (line 453) calls the `/get-session` endpoint internally. A cookie cache optimization provides fast reads, but the DB is the authority. The `sensitiveSessionMiddleware` (line 561) forces a DB-backed authoritative read by disabling the cookie cache. The Next.js integration (`toNextJsHandler` in next-js.ts:8) simply wraps this same handler — all framework integrations delegate to the same `getSessionFromCtx` function.

```typescript
export const getSession = <Option extends BetterAuthOptions>() =>
	createAuthEndpoint(
		"/get-session",
		{
			method: ["GET", "POST"],
			operationId: "getSession",
			query: getSessionQuerySchema,
			requireHeaders: true,
		},
		async (ctx) => {
			ctx.setHeader("cache-control", "no-store");
			const sessionCookieToken = await ctx.getSignedCookie(
				ctx.context.authCookies.sessionToken.name,
				ctx.context.secret,
			);
			if (!sessionCookieToken) return null;
			const session = await ctx.context.internalAdapter.findSession(sessionCookieToken);
			ctx.context.session = session;
			if (!session || session.session.expiresAt < new Date()) {
				deleteSessionCookie(ctx);
				if (session) {
					await ctx.context.internalAdapter.deleteSession(session.session.token);
				}
				return ctx.json(null);
			}
			return ctx.json({ session: session.session, user: session.user });
		},
	);

export const getSessionFromCtx = async (ctx, config?) => {
	if (ctx.context.session) return ctx.context.session;
	const session = await getSession()({ ...ctx, method: "GET", asResponse: false }).catch(() => null);
	if (!session) { ctx.context.session = null; return null; }
	ctx.context.session = session.response;
	return session.response;
};

export const sensitiveSessionMiddleware = createAuthMiddleware(async (ctx) => {
	const session = await getAuthoritativeSessionFromCtx(ctx);
	if (!session?.session) throw APIError.from("UNAUTHORIZED", { message: "Unauthorized", code: "UNAUTHORIZED" });
	return { session };
});
```
